func (r *OrderSQLiteRepository) FindMany(ctx context.Context, filter *OrderFilter, opts *OrderFindOptions) ([]*types.Order, int, error) {
	if opts == nil || opts.Fields.IsZero() {
		return nil, 0, fmt.Errorf("fields must be specified in FindOptions for performance")
	}
	var args []any
	where := r.where(filter, &args, opts.IncludeDeleted)
	records, total, err := orderSQLite.findMany(ctx, r.q(), where, r.orderBy(opts.OrderBy), args, opts.Limit, opts.Offset, opts.SkipCount)
	if err != nil {
		return nil, 0, err
	}
	rows, err := r.decode(ctx, records, opts.Fields, true)
	if err != nil {
		return nil, 0, err
	}
	return rows, total, nil
}

// findRelated reads the rows filter finds as FindMany reads them, with no
// count: the read that loads a relation's rows for another table's read.
func (r *OrderSQLiteRepository) findRelated(ctx context.Context, filter *OrderFilter, opts *OrderFindOptions) ([]*types.Order, error) {
	skip := *opts
	skip.SkipCount = true
	rows, _, err := r.FindMany(ctx, filter, &skip)
	return rows, err
}

// FindPage reads a page of the Order rows filter finds, in the
// sort's order, after the key of the page before (D60, amended).
func (r *OrderSQLiteRepository) FindPage(ctx context.Context, filter *OrderFilter, opts *OrderPageOptions) (*OrderPage, error) {
	if opts == nil || opts.Fields.IsZero() {
		return nil, fmt.Errorf("fields must be specified in PageOptions for performance")
	}
	if opts.Limit < 0 {
		return nil, fmt.Errorf("orm: a page of Order rows holds 1 or more, not %d", opts.Limit)
	}
	limit := opts.Limit
	if limit == 0 {
		limit = 100
	}
	field := opts.Sort.Field
	if field == "" {
		field = OrderSortById
	}
	column, ok := orderSortColumns[field]
	if !ok {
		return nil, fmt.Errorf("orm: Order sorts by id, title, placedAt, status and statusEnteredAt, not %q", string(field))
	}
	var after any
	if opts.After != nil {
		if _, err := opts.After.arg(); err != nil {
			return nil, err
		}
		key, err := orderSQLite.keyArg(opts.After.Id)
		if err != nil {
			return nil, err
		}
		after = key
	}
	var args []any
	conditions := filter.sqliteConditions(&args)
	records, err := orderSQLite.page(ctx, r.q(), conditions, args, sqliteSort{sql: column.sql, key: column.key, nulls: column.nulls}, field == OrderSortById, opts.Sort.Desc, after, limit, opts.IncludeDeleted)
	if err != nil {
		return nil, err
	}
	// Next is the key of the page's last row, so the page reads its
	// primary key whatever Fields selects.
	fields := opts.Fields
	fields.Id = true
	rows, err := r.decode(ctx, records, fields, true)
	if err != nil {
		return nil, err
	}
	page := &OrderPage{Rows: rows}
	if len(rows) > limit {
		page.Rows = rows[:limit]
		page.Next = orderPageKeyOf(page.Rows[limit-1])
	}
	return page, nil
}

// stampCreate sets the audit fields of who wrote input, as the Postgres
// repository's CreateOne does.
func (r *OrderSQLiteRepository) stampCreate(ctx context.Context, input *types.Order) error {
	return nil
}

// pg is Order's Postgres repository on no connection, whose
// conversions of a row to the behaviors' core's own fields, and of a write
// to its columns and its stamps, this one runs, its columns then held as
// SQLite holds them (D103, D116).
func (r *OrderSQLiteRepository) pg() *OrderRepository { return &OrderRepository{} }

// operationOptions are the stamps an operation's write of the row sets, as
// SQLite holds them.
func (r *OrderSQLiteRepository) operationOptions(ctx context.Context) (*rules.ExecuteOptions, error) {
	opts := r.pg().operationOptions(ctx)
	if opts == nil {
		return nil, nil
	}
	converted := *opts
	columns, err := orderSQLite.coreColumns(opts.OwnColumns)
	if err != nil {
		return nil, err
	}
	converted.OwnColumns = columns
	return &converted, nil
}

// inTx runs fn in the repository's transaction, or in one of its own.
func (r *OrderSQLiteRepository) inTx(ctx context.Context, fn func(tx *sql.Tx) error) error {
	return r.within(ctx, func(q sqliteQuerier) error { return fn(q.(*sql.Tx)) })
}

// CreateOne creates a Order row through the behaviors' core (D103), in a
// transaction, whose uses initialize the fields they own, and reads it back.
func (r *OrderSQLiteRepository) CreateOne(ctx context.Context, input *OrderCreate) (*types.Order, error) {
	var out *types.Order
	err := r.inTx(ctx, func(tx *sql.Tx) error {
		pg := r.pg()
		row := input.row()
		if err := r.stampCreate(ctx, row); err != nil {
			return err
		}
		columns, err := pg.createColumns(row)
		if err != nil {
			return err
		}
		if columns, err = orderSQLite.coreColumns(columns); err != nil {
			return err
		}
		opts := &rules.CreateOptions{ID: pg.createKey(row), ExecuteOptions: rules.ExecuteOptions{OwnColumns: columns}}
		key, err := rules.RunCreate(ctx, sqliteRulesHost(tx), "Order", pg.coreOwn(row), behaviorCaller(ctx), opts)
		if err != nil {
			return err
		}
		id, err := types.ParseIdentityUUID(key)
		if err != nil {
			return fmt.Errorf("create Order: the core's key %q: %w", key, err)
		}
		out, err = (&OrderSQLiteRepository{db: r.db, tx: tx}).GetOne(ctx, id, nil)
		return err
	})
	return out, err
}

// UpdateOne updates a single Order row by ID through the behaviors' core
// (D103), in a transaction: the own fields update sets, and the row is read
// back. It returns ErrNotFound when no live row holds id, and any other
// refusal of the core's as the *rules.Refusal it is.
func (r *OrderSQLiteRepository) UpdateOne(ctx context.Context, id types.IdentityUUID, update *OrderUpdate) (*types.Order, error) {
	if update == nil {
		update = &OrderUpdate{}
	}
	var out *types.Order
	err := r.inTx(ctx, func(tx *sql.Tx) error {
		pg := r.pg()
		patch := pg.corePatch(update)
		columns, err := pg.updateColumns(ctx, update)
		if err != nil {
			return err
		}
		if len(patch) == 0 && len(columns) == 0 {
			return fmt.Errorf("no fields to update")
		}
		if columns, err = orderSQLite.coreColumns(columns); err != nil {
			return err
		}
		if err := rules.RunUpdate(ctx, sqliteRulesHost(tx), "Order", id.String(), patch, behaviorCaller(ctx), &rules.ExecuteOptions{OwnColumns: columns}); err != nil {
			return behaviorNotFound(err, "Order", id)
		}
		out, err = (&OrderSQLiteRepository{db: r.db, tx: tx}).GetOne(ctx, id, nil)
		return err
	})
	return out, err
}

// DeleteOne deletes a single Order row by ID through the behaviors' core
// (D103), in a transaction. It returns ErrNotFound when no live row holds id, and any other
// refusal of the core's as the *rules.Refusal it is.
func (r *OrderSQLiteRepository) DeleteOne(ctx context.Context, id types.IdentityUUID) error {
	return r.inTx(ctx, func(tx *sql.Tx) error {
		opts := &rules.ExecuteOptions{}
		if err := rules.RunDelete(ctx, sqliteRulesHost(tx), "Order", id.String(), behaviorCaller(ctx), opts); err != nil {
			return behaviorNotFound(err, "Order", id)
		}
		return nil
	})
}

// UpsertOne is refused on SQLite: an upsert of a table that composes
// behaviors runs on Postgres alone (D116).
func (r *OrderSQLiteRepository) UpsertOne(context.Context, *OrderCreate, OrderUniqueKey, *OrderUpdate) (*types.Order, error) {
	return nil, sqliteRefused("Order", "composes behaviors, whose upserts run on Postgres alone")
}

// UpsertOneResult is refused on SQLite, as UpsertOne is.
func (r *OrderSQLiteRepository) UpsertOneResult(context.Context, *OrderCreate, OrderUniqueKey, *OrderUpdate, *UpsertOptions) (UpsertResult[*types.Order], error) {
	return UpsertResult[*types.Order]{}, sqliteRefused("Order", "composes behaviors, whose upserts run on Postgres alone")
}

// UpsertMany is refused on SQLite, as UpsertOne is.
func (r *OrderSQLiteRepository) UpsertMany(context.Context, []*OrderCreate, OrderUniqueKey, OrderFields, *UpsertOptions) ([]UpsertResult[*types.Order], error) {
	return nil, sqliteRefused("Order", "composes behaviors, whose upserts run on Postgres alone")
}

// Status returns the operations of Order's status on SQLite.
func (r *OrderSQLiteRepository) Status() OrderStatusOperations {
	return orderSQLiteStatusOperations{r: r}
}

// orderSQLiteStatusOperations runs OrderStatusOperations through the behaviors' core on the SQLite
// repository's transaction, or one of its own.
type orderSQLiteStatusOperations struct{ r *OrderSQLiteRepository }

// Transition runs status's transition in a transaction, as the Postgres
// repository's does.
func (o orderSQLiteStatusOperations) Transition(ctx context.Context, id types.IdentityUUID, params OrderStatusTransitionParams) (*OrderStatusTransitionResult, error) {
	var out *OrderStatusTransitionResult
	err := o.r.inTx(ctx, func(tx *sql.Tx) error {
		opts, err := o.r.operationOptions(ctx)
		if err != nil {
			return err
		}
		raw, err := rules.RunOperation(ctx, sqliteRulesHost(tx), "Order", id.String(), "status", "transition", params, behaviorCaller(ctx), opts)
		if err != nil {
			return behaviorNotFound(err, "Order", id)
		}
		out = &OrderStatusTransitionResult{}
		if err := json.Unmarshal(raw, out); err != nil {
			return fmt.Errorf("orm: the result of Order's status transition, %s: %w", raw, err)
		}
		return nil
	})
	if err != nil {
		var zero *OrderStatusTransitionResult
		return zero, err
	}
	return out, nil
}

// CreateMany inserts the rows, in order, each a create of the behaviors'
// core (D103), in one transaction.
func (r *OrderSQLiteRepository) CreateMany(ctx context.Context, inputs []*OrderCreate) ([]*types.Order, error) {
	out := make([]*types.Order, 0, len(inputs))
	if len(inputs) == 0 {
		return out, nil
	}
	err := r.within(ctx, func(q sqliteQuerier) error {
		in := &OrderSQLiteRepository{db: r.db, tx: q.(*sql.Tx)}
		for _, input := range inputs {
			row, err := in.CreateOne(ctx, input)
			if err != nil {
				return err
			}
			out = append(out, row)
		}
		return nil
	})
	if err != nil {
		return nil, err
	}
	return out, nil
}

// sets are update's assignments, each value appended to args after those
// already there, and the columns they set and their values, which an
// upsert only if changed compares (D89).
func (r *OrderSQLiteRepository) sets(update *OrderUpdate, args *[]any) (sets, compare, next []string, err error) {
	if update == nil {
		return nil, nil, nil, nil
	}
	if update.Title != nil {
		value, err := orderSQLite.arg(*update.Title, 1)
		if err != nil {
			return nil, nil, nil, err
		}
		*args = append(*args, value)
		sets = append(sets, fmt.Sprintf(`title = ?%d`, len(*args)))
		compare, next = append(compare, `"order".title`), append(next, fmt.Sprintf("?%d", len(*args)))
	}
	if update.PlacedAt != nil && update.PlacedAtSetNull {
		return nil, nil, nil, fmt.Errorf("placed_at cannot be updated with both value and null assignment")
	}
	if update.PlacedAtSetNull {
		sets = append(sets, `placed_at = NULL`)
		compare, next = append(compare, `"order".placed_at`), append(next, `NULL`)
	} else if update.PlacedAt != nil {
		value, err := orderSQLite.arg(*update.PlacedAt, 2)
		if err != nil {
			return nil, nil, nil, err
		}
		*args = append(*args, value)
		sets = append(sets, fmt.Sprintf(`placed_at = ?%d`, len(*args)))
		compare, next = append(compare, `"order".placed_at`), append(next, fmt.Sprintf("?%d", len(*args)))
	}
	return sets, compare, next, nil
}

// updatedBy is who an update says it was made by: its own UpdatedBy, the
// acting user, or nil.
func (r *OrderSQLiteRepository) updatedBy(ctx context.Context, update *OrderUpdate) (any, error) {
	return nil, nil
}

// stamped are sets with the stamps of an update after them and each
// fence they advance (D119).
func (r *OrderSQLiteRepository) stamped(ctx context.Context, update *OrderUpdate, sets []string, args []any) ([]string, []any, error) {
	by, err := r.updatedBy(ctx, update)
	if err != nil {
		return nil, nil, err
	}
	sets, args = orderSQLite.stamp(sets, args, by)
	return sets, args, nil
}

// UpdateMany sets the members update sets on the live rows filter finds,
// and answers how many.
func (r *OrderSQLiteRepository) UpdateMany(ctx context.Context, filter *OrderFilter, update *OrderUpdate) (int, error) {
	var args []any
	sets, _, _, err := r.sets(update, &args)
	if err != nil {
		return 0, err
	}
	if sets, args, err = r.stamped(ctx, update, sets, args); err != nil {
		return 0, err
	}
	if len(sets) == 0 {
		return 0, fmt.Errorf("no fields to update")
	}
	where := r.where(filter, &args, false)
	n, err := orderSQLite.exec(ctx, r.q(), fmt.Sprintf(orderSQLite.st.updateMany, strings.Join(sets, ", "), where), args...)
	if err != nil {
		return 0, fmt.Errorf("failed to execute update: %w", err)
	}
	return n, nil
}

// deletedBy is the acting user a delete stamps, and ErrNoUserInContext
// without one on a table that stamps it.
func (r *OrderSQLiteRepository) deletedBy(ctx context.Context) (any, error) {
	return nil, nil
}

// DeleteMany deletes the live rows filter finds, and
// answers how many.
func (r *OrderSQLiteRepository) DeleteMany(ctx context.Context, filter *OrderFilter) (int, error) {
	by, err := r.deletedBy(ctx)
	if err != nil {
		return 0, err
	}
	return orderSQLite.deleteMany(ctx, r.q(), filter.sqliteConditions, by)
}
